try {
    const stored = localStorage.getItem(this.STORAGE_KEY);
    return stored ? JSON.parse(stored) : {};
} catch (e) {
    console.error("Errors parsing search config from localStorage", e);
    return {};
}

const allConfigs = this._getAllConfigs();

allConfigs[pageKey] = {
    property,
    operation,
    lastUpdated: new Date().toISOString()
}

localStorage.setItem(this.STORAGE_KEY, JSON.stringify(allConfigs));

const allConfigs = this._getAllConfigs();

if (allConfigs[pageKey]) {
    delete allConfigs[pageKey];
    localStorage.setItem(this.STORAGE_KEY, JSON.stringify(allConfigs));
}
